// Replaces the class normally generated by the BepInEx.PluginInfoProps NuGet
// package. This project builds without NuGet (see OcAI.csproj), so the plugin
// metadata constants are declared by hand. Keep in sync with the csproj Version.
namespace OcAI
{
    internal static class MyPluginInfo
    {
        public const string PLUGIN_GUID = "com.lenovo.ocdesktop.ocai";
        public const string PLUGIN_NAME = "OC AI Companion";
        public const string PLUGIN_VERSION = "0.2.0";
    }
}
